INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LT0CRjun0kd', 4, '{"title":"第20200224条・灵兰秘典论篇第八","description":"<p>13、膀胱者。州都之官。津液藏焉。气化则能出矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200224,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '13、膀胱者。州都之官。津液藏焉。气化则能出矣。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'XrettJNHEeX');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('sgmd2BUm2Hu', 4, '{"title":"第20200225条・灵兰秘典论篇第八","description":"<p>14、凡此十二官者。不得相失也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200225,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '14、凡此十二官者。不得相失也。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'XrettJNHEeX');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6BnlwO6KyHR', 4, '{"title":"第20200226条・灵兰秘典论篇第八","description":"<p>15、故主明则下安。以此养生则寿。殁世不殆，以为天下则大昌。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200226,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '15、故主明则下安。以此养生则寿。殁世不殆，以为天下则大昌。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'XrettJNHEeX');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Sb0YUHiPE3H', 4, '{"title":"第20200227条・灵兰秘典论篇第八","description":"<p>16、主不明则十二官危。使道闭塞而不通。形乃大伤。以此养生则殃。以为天下者。其宗大危。戒之戒之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200227,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '16、主不明则十二官危。使道闭塞而不通。形乃大伤。以此养生则殃。以为天下者。其宗大危。戒之戒之。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'XrettJNHEeX');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('k3pbyXNyUDF', 4, '{"title":"第20200228条・灵兰秘典论篇第八","description":"<p>17、至道在微。变化无穷。孰知其原。窘乎哉。消者瞿瞿。孰知其要。闵闵之当。孰者为良。恍惚之数。生于毫釐。毫釐之数，起于度量。千之万之。可以益大。推之大之。其形乃制。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200228,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '17、至道在微。变化无穷。孰知其原。窘乎哉。消者瞿瞿。孰知其要。闵闵之当。孰者为良。恍惚之数。生于毫釐。毫釐之数，起于度量。千之万之。可以益大。推之大之。其形乃制。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'XrettJNHEeX');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JLgpVHMVII2', 4, '{"title":"第20200229条・灵兰秘典论篇第八","description":"<p>18、黄帝曰：善哉。余闻精光之道。大圣之业。而宣明大道。非斋戒择吉日。不敢受也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200229,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '18、黄帝曰：善哉。余闻精光之道。大圣之业。而宣明大道。非斋戒择吉日。不敢受也。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'XrettJNHEeX');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ywsqdp19HWO', 4, '{"title":"第20200230条・灵兰秘典论篇第八","description":"<p>19、黄帝乃择吉日良兆。而藏灵兰之室。以传保焉。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200230,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '19、黄帝乃择吉日良兆。而藏灵兰之室。以传保焉。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'XrettJNHEeX');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jykG5bIdAF8', 4, '{"title":"第20200231条・六节藏象论篇第九","description":"<p>1、黄帝问曰：余闻天以六六之节。以成一岁。人以九九制会。计人亦有三百六十五节。以为天地久矣。不知其所谓也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200231,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '1、黄帝问曰：余闻天以六六之节。以成一岁。人以九九制会。计人亦有三百六十五节。以为天地久矣。不知其所谓也？', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0pHojq4V4GR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cdImJpliyhJ', 4, '{"title":"第20200232条・六节藏象论篇第九","description":"<p>2、岐伯对曰：昭乎哉问也。请遂言之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200232,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2、岐伯对曰：昭乎哉问也。请遂言之。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0pHojq4V4GR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4k81CTMqK5M', 4, '{"title":"第20200233条・六节藏象论篇第九","description":"<p>3、夫六六之节。九九制会者。所以正天之度。气之数也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200233,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '3、夫六六之节。九九制会者。所以正天之度。气之数也。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0pHojq4V4GR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('V8M0Ea5mgoS', 4, '{"title":"第20200234条・六节藏象论篇第九","description":"<p>4、天度者。所以制日月之行也。气数者。所以纪化生之用也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200234,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '4、天度者。所以制日月之行也。气数者。所以纪化生之用也。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0pHojq4V4GR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yrxHQp7NPLq', 4, '{"title":"第20200235条・六节藏象论篇第九","description":"<p>5、天为阳。地为阴。日为阳。月为阴。行有分纪。周有道理。日行一度。月行十三度而有奇焉。故大小月三百六十五日而成岁。积气余而盈闰矣。立端于始。表正于中。推余于终。而天度毕矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200235,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '5、天为阳。地为阴。日为阳。月为阴。行有分纪。周有道理。日行一度。月行十三度而有奇焉。故大小月三百六十五日而成岁。积气余而盈闰矣。立端于始。表正于中。推余于终。而天度毕矣。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0pHojq4V4GR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('j75dPPUqsE9', 4, '{"title":"第20200236条・六节藏象论篇第九","description":"<p>6、帝曰：余已闻天度矣。愿闻气数何以合之？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200236,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '6、帝曰：余已闻天度矣。愿闻气数何以合之？', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0pHojq4V4GR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ds83If46Ii5', 4, '{"title":"第20200237条・六节藏象论篇第九","description":"<p>7、岐伯曰：天以六六为节。地以九九制会。天有十日。日六竟而周甲。甲六复而终岁。三百六十日法也。夫自古通天者。生之本。本于阴阳。其气九州九窍。皆通乎天气。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200237,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '7、岐伯曰：天以六六为节。地以九九制会。天有十日。日六竟而周甲。甲六复而终岁。三百六十日法也。夫自古通天者。生之本。本于阴阳。其气九州九窍。皆通乎天气。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0pHojq4V4GR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Nu7D2MWVwr0', 4, '{"title":"第20200238条・六节藏象论篇第九","description":"<p>8、故其生五。其气三。三而成天。三而成地。三而成人。三而三之。合则为九。九分为九野。九野为九藏。故形藏四。神藏五。合为九藏以应之也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200238,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '8、故其生五。其气三。三而成天。三而成地。三而成人。三而三之。合则为九。九分为九野。九野为九藏。故形藏四。神藏五。合为九藏以应之也。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0pHojq4V4GR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Gf6WdFnMI6z', 4, '{"title":"第20200239条・六节藏象论篇第九","description":"<p>9、帝曰：余已闻六六九九之会也。夫子言积气盈闰。愿闻何谓气？请夫子发蒙解惑焉。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200239,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '9、帝曰：余已闻六六九九之会也。夫子言积气盈闰。愿闻何谓气？请夫子发蒙解惑焉。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0pHojq4V4GR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3bRP7mN3OJ9', 4, '{"title":"第20200240条・六节藏象论篇第九","description":"<p>10、岐伯曰：此上帝所秘。先师传之也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200240,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '10、岐伯曰：此上帝所秘。先师传之也。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0pHojq4V4GR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('eZk0UJQXHcX', 4, '{"title":"第20200241条・六节藏象论篇第九","description":"<p>11、帝曰：请遂闻之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200241,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '11、帝曰：请遂闻之。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0pHojq4V4GR');
