INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HfnXjWvLMFc', 4, '{"title":"第20200250条・六节藏象论篇第九","description":"<p>20、岐伯曰：春胜长夏。长夏胜冬。冬胜夏。夏胜秋。秋胜春。所谓得五行时之胜。各以气命其脏。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200250,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '20、岐伯曰：春胜长夏。长夏胜冬。冬胜夏。夏胜秋。秋胜春。所谓得五行时之胜。各以气命其脏。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0pHojq4V4GR');
