INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BAjWqWD1dFe', 4, '{"title":"第20200252条・六节藏象论篇第九","description":"<p>22、岐伯曰：求其至也。皆归始春。未至而至。此谓太过。则薄所不胜。而乘所胜也。命曰气淫。不分邪僻内生。工不能禁。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200252,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '22、岐伯曰：求其至也。皆归始春。未至而至。此谓太过。则薄所不胜。而乘所胜也。命曰气淫。不分邪僻内生。工不能禁。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0pHojq4V4GR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AP593Whah8O', 4, '{"title":"第20200253条・六节藏象论篇第九","description":"<p>23、至而不至。此谓不及。则所胜妄行。而所生受病。所不胜薄之也。命曰气迫。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200253,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '23、至而不至。此谓不及。则所胜妄行。而所生受病。所不胜薄之也。命曰气迫。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0pHojq4V4GR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5HVIrYqKPq5', 4, '{"title":"第20200254条・六节藏象论篇第九","description":"<p>24、所谓求其至者。气至之时也。谨候其时。气可与期。失时反候。五治不分。邪僻内生。工不能禁也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200254,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '24、所谓求其至者。气至之时也。谨候其时。气可与期。失时反候。五治不分。邪僻内生。工不能禁也。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0pHojq4V4GR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VsTFBBZTVTr', 4, '{"title":"第20200255条・六节藏象论篇第九","description":"<p>25、帝曰：有不袭乎。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200255,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '25、帝曰：有不袭乎。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0pHojq4V4GR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('rbaPbrjvtHG', 4, '{"title":"第20200256条・六节藏象论篇第九","description":"<p>26、岐伯曰：苍天之气。不得无常也。气之不袭。是谓非常。非常则变矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200256,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '26、岐伯曰：苍天之气。不得无常也。气之不袭。是谓非常。非常则变矣。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0pHojq4V4GR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9mhv9bvVHsi', 4, '{"title":"第20200257条・六节藏象论篇第九","description":"<p>27、帝曰：非常而变奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200257,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '27、帝曰：非常而变奈何？', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0pHojq4V4GR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('teIQglw71RG', 4, '{"title":"第20200258条・六节藏象论篇第九","description":"<p>28、岐伯曰：变至则病。所胜则微。所不胜则甚。因而重感于邪。则死矣。 故非其时则微。当其时则甚也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200258,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '28、岐伯曰：变至则病。所胜则微。所不胜则甚。因而重感于邪。则死矣。 故非其时则微。当其时则甚也。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0pHojq4V4GR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZVAy3GZ0keT', 4, '{"title":"第20200259条・六节藏象论篇第九","description":"<p>29、帝曰：善。余闻气合而有形，因变以正名。天地之运。阴阳之化。其于万物。 孰少孰多。可得闻乎？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200259,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '29、帝曰：善。余闻气合而有形，因变以正名。天地之运。阴阳之化。其于万物。 孰少孰多。可得闻乎？', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0pHojq4V4GR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VSTpKeLYaUt', 4, '{"title":"第20200260条・六节藏象论篇第九","description":"<p>30、岐伯曰：悉哉问也。天至广不可度。地至大不可量。大神灵问。请陈其方。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200260,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '30、岐伯曰：悉哉问也。天至广不可度。地至大不可量。大神灵问。请陈其方。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0pHojq4V4GR');
