INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iZn5grpcodP', 4, '{"title":"第20200267条・六节藏象论篇第九","description":"<p>37、岐伯曰：心者。生之本。神之变也。其华在面。其充在血脉。为阳中之太阳。通于夏气。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200267,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '37、岐伯曰：心者。生之本。神之变也。其华在面。其充在血脉。为阳中之太阳。通于夏气。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0pHojq4V4GR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SYRNIxrDOg5', 4, '{"title":"第20200268条・六节藏象论篇第九","description":"<p>38、肺者。气之本。魄之处也。其华在毛。其充在皮。为阳中之太阴。通于秋气。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200268,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '38、肺者。气之本。魄之处也。其华在毛。其充在皮。为阳中之太阴。通于秋气。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0pHojq4V4GR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('j9ox1iq8ZHn', 4, '{"title":"第20200269条・六节藏象论篇第九","description":"<p>39、肾者。主蛰封藏之本。精之处也。其华在发。其充在骨。为阴中之少阴。通于冬气。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200269,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '39、肾者。主蛰封藏之本。精之处也。其华在发。其充在骨。为阴中之少阴。通于冬气。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0pHojq4V4GR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VNqVAaw3gLj', 4, '{"title":"第20200270条・六节藏象论篇第九","description":"<p>40、肝者。罢极之本。魂之居也。其华在爪。其充在筋。以生血气。其味酸。其色苍。此为阳中之少阳。通于春气。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200270,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '40、肝者。罢极之本。魂之居也。其华在爪。其充在筋。以生血气。其味酸。其色苍。此为阳中之少阳。通于春气。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0pHojq4V4GR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xkGdvKxRIBX', 4, '{"title":"第20200271条・六节藏象论篇第九","description":"<p>41、脾胃大肠小肠三焦膀胱者。仓廪之本。营之居也。名曰器。能化糟粕。转味而入出者也。其华在唇四白。其充在肌。其味甘。其色黄。此至阴之类。通于土气。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200271,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '41、脾胃大肠小肠三焦膀胱者。仓廪之本。营之居也。名曰器。能化糟粕。转味而入出者也。其华在唇四白。其充在肌。其味甘。其色黄。此至阴之类。通于土气。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0pHojq4V4GR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('o5qy3VZs9Qe', 4, '{"title":"第20200272条・六节藏象论篇第九","description":"<p>42、凡十一脏。取决于胆也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200272,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '42、凡十一脏。取决于胆也。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0pHojq4V4GR');
