INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('sRGiOmw6a3Z', 4, '{"title":"第20200274条・六节藏象论篇第九","description":"<p>44、人迎与寸口俱盛四倍以上为关格。关格之脉羸。不能极于天地之精气。则死矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200274,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '44、人迎与寸口俱盛四倍以上为关格。关格之脉羸。不能极于天地之精气。则死矣。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', '0pHojq4V4GR');
