INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zpHdVaw0hxN', 4, '{"title":"第20200284条・五脏生成篇第十","description":"<p>10、多食甘。则骨痛而发落。此五味之所伤也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200284,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '10、多食甘。则骨痛而发落。此五味之所伤也。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'dgkwGGmrOui');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TY2PgC7R3VY', 4, '{"title":"第20200285条・五脏生成篇第十","description":"<p>11、故心欲苦。肺欲辛。肝欲酸。脾欲甘。肾欲咸。此五味之所合五脏之气也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200285,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '11、故心欲苦。肺欲辛。肝欲酸。脾欲甘。肾欲咸。此五味之所合五脏之气也。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'dgkwGGmrOui');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qKIuXNJe2Vd', 4, '{"title":"第20200286条・五脏生成篇第十","description":"<p>12、故色见青如草兹者死。黄如枳实者死。黑如者死。赤如衃血者死。白如枯骨者死。此五色之见死也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200286,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '12、故色见青如草兹者死。黄如枳实者死。黑如者死。赤如衃血者死。白如枯骨者死。此五色之见死也。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'dgkwGGmrOui');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mQOMk4Gd3j1', 4, '{"title":"第20200287条・五脏生成篇第十","description":"<p>13、青如翠羽者生。赤如鸡冠者生。黄如蟹腹者生。白如豕膏者生。黑如乌羽者生。此五色之见生也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200287,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '13、青如翠羽者生。赤如鸡冠者生。黄如蟹腹者生。白如豕膏者生。黑如乌羽者生。此五色之见生也。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'dgkwGGmrOui');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IpG6Yt5mzqv', 4, '{"title":"第20200288条・五脏生成篇第十","description":"<p>14、生于心。如以缟裹朱。生于肺如以缟裹红。生于肝如以缟裹绀。生于脾如以缟裹栝蒌实。生于肾如以缟裹紫。此五脏所生之外荣也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200288,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '14、生于心。如以缟裹朱。生于肺如以缟裹红。生于肝如以缟裹绀。生于脾如以缟裹栝蒌实。生于肾如以缟裹紫。此五脏所生之外荣也。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'dgkwGGmrOui');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('g2tqHngNhiN', 4, '{"title":"第20200289条・五脏生成篇第十","description":"<p>15、色味当五脏。白当肺。辛。赤当心。苦。青当肝。酸。黄当脾。甘。黑当肾。咸。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200289,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '15、色味当五脏。白当肺。辛。赤当心。苦。青当肝。酸。黄当脾。甘。黑当肾。咸。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'dgkwGGmrOui');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('sc3jQgVBd1J', 4, '{"title":"第20200290条・五脏生成篇第十","description":"<p>16、故白当皮。赤当脉。青当筋。黄当肉。黑当骨。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200290,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '16、故白当皮。赤当脉。青当筋。黄当肉。黑当骨。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'dgkwGGmrOui');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lHYVz6OAqJ6', 4, '{"title":"第20200291条・五脏生成篇第十","description":"<p>17、诸脉者皆属于目。诸髓者皆属于脑。诸筋者皆属于节。诸血者皆属于心。诸气者皆属于肺。此四肢八溪之朝夕也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200291,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '17、诸脉者皆属于目。诸髓者皆属于脑。诸筋者皆属于节。诸血者皆属于心。诸气者皆属于肺。此四肢八溪之朝夕也。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'dgkwGGmrOui');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wDy5gwzqhP0', 4, '{"title":"第20200292条・五脏生成篇第十","description":"<p>18、故人卧血归于肝。肝受血而能视。足受血而能步。掌受血而能握。指受血而能摄。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200292,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '18、故人卧血归于肝。肝受血而能视。足受血而能步。掌受血而能握。指受血而能摄。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'dgkwGGmrOui');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Jwsq7C8DUNO', 4, '{"title":"第20200293条・五脏生成篇第十","description":"<p>19、卧出而风吹之。血凝于肤者为痹。凝于脉者为泣。凝于足者为厥。此三者。血行而不得反其空。故为痹厥也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200293,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '19、卧出而风吹之。血凝于肤者为痹。凝于脉者为泣。凝于足者为厥。此三者。血行而不得反其空。故为痹厥也。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'dgkwGGmrOui');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JREhmSlt2fZ', 4, '{"title":"第20200294条・五脏生成篇第十","description":"<p>20、人有大谷十二分。小溪三百五十四名。少十二俞。此皆卫气之所留止。邪气之所客也。针石缘而去之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200294,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '20、人有大谷十二分。小溪三百五十四名。少十二俞。此皆卫气之所留止。邪气之所客也。针石缘而去之。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'dgkwGGmrOui');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('INcnzSTX2CI', 4, '{"title":"第20200295条・五脏生成篇第十","description":"<p>21、诊病之始。五决为纪。欲知其始。先建其母。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200295,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '21、诊病之始。五决为纪。欲知其始。先建其母。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'dgkwGGmrOui');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HrTIlDl5bTU', 4, '{"title":"第20200296条・五脏生成篇第十","description":"<p>22、所谓五决者。五脉也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200296,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '22、所谓五决者。五脉也。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'dgkwGGmrOui');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('haSWiSEx41J', 4, '{"title":"第20200297条・五脏生成篇第十","description":"<p>23、是以头痛巅疾。下虚上实。过在足少阴。巨阳。甚则入肾。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200297,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '23、是以头痛巅疾。下虚上实。过在足少阴。巨阳。甚则入肾。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'dgkwGGmrOui');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('UjYR5HMAI6r', 4, '{"title":"第20200298条・五脏生成篇第十","description":"<p>24、徇蒙招尤。目冥耳聋。下实上虚。过在足少阳厥阴。甚则入肝。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200298,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '24、徇蒙招尤。目冥耳聋。下实上虚。过在足少阳厥阴。甚则入肝。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'dgkwGGmrOui');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gk4hNoeEpnp', 4, '{"title":"第20200299条・五脏生成篇第十","description":"<p>25、腹满胀。支膈胠胁。下厥上冒。过在足太阴。阳明。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200299,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '25、腹满胀。支膈胠胁。下厥上冒。过在足太阴。阳明。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'dgkwGGmrOui');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PZk1cA4R22l', 4, '{"title":"第20200300条・五脏生成篇第十","description":"<p>26、咳嗽上气。厥在胸中。过在手阳明。太阴。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200300,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '26、咳嗽上气。厥在胸中。过在手阳明。太阴。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'dgkwGGmrOui');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kUr3ileaO98', 4, '{"title":"第20200301条・五脏生成篇第十","description":"<p>27、心烦头痛。病在膈中。过在手巨阳。少阴。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200301,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '27、心烦头痛。病在膈中。过在手巨阳。少阴。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'dgkwGGmrOui');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('uPpY625DbxQ', 4, '{"title":"第20200302条・五脏生成篇第十","description":"<p>28、夫脉之小大滑涩浮沉。可以指别。五藏之象。可以类推。五藏相音。可以意识。五色微诊。可以目察。能合脉色。可以万全。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200302,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '28、夫脉之小大滑涩浮沉。可以指别。五藏之象。可以类推。五藏相音。可以意识。五色微诊。可以目察。能合脉色。可以万全。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'dgkwGGmrOui');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('rRxFdxYqghX', 4, '{"title":"第20200303条・五脏生成篇第十","description":"<p>29、赤脉之至也。喘而坚。诊曰有积气在中。时害于食。名曰心痹。得之外疾。思虑而心虚。故邪从之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200303,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '29、赤脉之至也。喘而坚。诊曰有积气在中。时害于食。名曰心痹。得之外疾。思虑而心虚。故邪从之。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'dgkwGGmrOui');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GxdQG91TNi8', 4, '{"title":"第20200304条・五脏生成篇第十","description":"<p>30、白脉之至也。喘而浮。上虚下实。惊。有积气在胸中。喘而虚。名曰肺痹寒热。得之醉而使内也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200304,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '30、白脉之至也。喘而浮。上虚下实。惊。有积气在胸中。喘而虚。名曰肺痹寒热。得之醉而使内也。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'dgkwGGmrOui');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('L7kqP3Xxq48', 4, '{"title":"第20200305条・五脏生成篇第十","description":"<p>31、青脉之至也。长而左右弹。有积气在心下支胠。名曰肝痹。得之寒湿。与疝同法。腰痛足清头痛。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200305,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '31、青脉之至也。长而左右弹。有积气在心下支胠。名曰肝痹。得之寒湿。与疝同法。腰痛足清头痛。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'dgkwGGmrOui');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('19itKhMIAlw', 4, '{"title":"第20200306条・五脏生成篇第十","description":"<p>32、黄脉之至也。大而虚。有积气在腹中。有厥气。名曰厥疝女子同法。得之疾使四肢汗出当风。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200306,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '32、黄脉之至也。大而虚。有积气在腹中。有厥气。名曰厥疝女子同法。得之疾使四肢汗出当风。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'dgkwGGmrOui');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wiop32gtJ1Q', 4, '{"title":"第20200307条・五脏生成篇第十","description":"<p>33、黑脉之至也。上坚而大。有积气在小腹与阴。名曰肾痹。得之沐浴清水而卧。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200307,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '33、黑脉之至也。上坚而大。有积气在小腹与阴。名曰肾痹。得之沐浴清水而卧。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'dgkwGGmrOui');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pFgWgXCKvCX', 4, '{"title":"第20200308条・五脏生成篇第十","description":"<p>34、凡相五色之奇脉。面黄目青。面黄目赤。面黄目白。面黄目黑者。皆不死也。面青目赤。面赤目白。面青目黑。面黑目白。面赤目青。皆死也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200308,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '34、凡相五色之奇脉。面黄目青。面黄目赤。面黄目白。面黄目黑者。皆不死也。面青目赤。面赤目白。面青目黑。面黑目白。面赤目青。皆死也。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'dgkwGGmrOui');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CdgQCtpTVU1', 4, '{"title":"第20200309条・五脏别论篇第十一","description":"<p>1、黄帝问曰：余闻方士。或以脑髓为藏。或以肠胃为藏。或以为腑。敢问更相反。皆自谓是。不知其道。愿闻其说。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200309,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '1、黄帝问曰：余闻方士。或以脑髓为藏。或以肠胃为藏。或以为腑。敢问更相反。皆自谓是。不知其道。愿闻其说。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', '53tEkUFZcdx');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5wXegf1q0Hq', 4, '{"title":"第20200310条・五脏别论篇第十一","description":"<p>2、岐伯对曰：脑髓骨脉胆女子胞。此六者地气之所生也。皆藏于阴而象于地。故藏而不泻。名曰奇恒之府。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200310,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2、岐伯对曰：脑髓骨脉胆女子胞。此六者地气之所生也。皆藏于阴而象于地。故藏而不泻。名曰奇恒之府。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', '53tEkUFZcdx');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('n0GPU74yXGG', 4, '{"title":"第20200311条・五脏别论篇第十一","description":"<p>3、夫胃大肠小肠三焦膀胱。此五者。天气之所生也。其气象天。故泻而不藏。此受五脏浊气。名曰传化之府。此不能久留输泻者也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200311,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '3、夫胃大肠小肠三焦膀胱。此五者。天气之所生也。其气象天。故泻而不藏。此受五脏浊气。名曰传化之府。此不能久留输泻者也。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', '53tEkUFZcdx');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dwkMQS7ovd2', 4, '{"title":"第20200312条・五脏别论篇第十一","description":"<p>4、魄门亦为五脏使。水谷不得久藏。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200312,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '4、魄门亦为五脏使。水谷不得久藏。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', '53tEkUFZcdx');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('F8bxHflt4Ez', 4, '{"title":"第20200313条・五脏别论篇第十一","description":"<p>5、所谓五藏者。藏精气而不泻也。故满而不能实。六腑者，传化物而不藏，故实而不能满也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200313,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '5、所谓五藏者。藏精气而不泻也。故满而不能实。六腑者，传化物而不藏，故实而不能满也。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', '53tEkUFZcdx');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('YcDhzZlQIE3', 4, '{"title":"第20200314条・五脏别论篇第十一","description":"<p>6、所以然者。水谷入口。则胃实而肠虚。食下。则肠实而胃虚。故曰实而不满。满而不实也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200314,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '6、所以然者。水谷入口。则胃实而肠虚。食下。则肠实而胃虚。故曰实而不满。满而不实也。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', '53tEkUFZcdx');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TnrOgwTupYK', 4, '{"title":"第20200315条・五脏别论篇第十一","description":"<p>7、帝曰：气口何以独为五脏主？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200315,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '7、帝曰：气口何以独为五脏主？', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', '53tEkUFZcdx');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LWJMBF9sxhY', 4, '{"title":"第20200316条・五脏别论篇第十一","description":"<p>8、岐伯曰：胃者。水谷之海。六腑之大源也。五味入口。藏于胃以养五脏气。气口亦太阴也。是以五藏六腑之气味。皆出于胃。变见于气口。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200316,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '8、岐伯曰：胃者。水谷之海。六腑之大源也。五味入口。藏于胃以养五脏气。气口亦太阴也。是以五藏六腑之气味。皆出于胃。变见于气口。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', '53tEkUFZcdx');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dFcBIJKOFEp', 4, '{"title":"第20200317条・五脏别论篇第十一","description":"<p>9、故五气入鼻。藏于心肺。心肺有病。而鼻为之不利也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200317,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '9、故五气入鼻。藏于心肺。心肺有病。而鼻为之不利也。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', '53tEkUFZcdx');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('U45Gr5sXUoF', 4, '{"title":"第20200318条・五脏别论篇第十一","description":"<p>10、凡治病必察其下。适其脉。观其志意。与其病也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200318,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '10、凡治病必察其下。适其脉。观其志意。与其病也。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', '53tEkUFZcdx');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7FfkcmnFTgM', 4, '{"title":"第20200319条・五脏别论篇第十一","description":"<p>11、拘于鬼神者。不可与言至德。恶于针石者。不可与言至巧。病不许治者。病必不治。治之无功矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200319,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '11、拘于鬼神者。不可与言至德。恶于针石者。不可与言至巧。病不许治者。病必不治。治之无功矣。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', '53tEkUFZcdx');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aYmfTfRzicZ', 4, '{"title":"第20200320条・异法方宜论篇第十二","description":"<p>1、黄帝问曰：医之治病也。一病而治各不同。皆愈何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200320,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '1、黄帝问曰：医之治病也。一病而治各不同。皆愈何也？', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'jzQX5jQGzs4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6lNLdmJJnwf', 4, '{"title":"第20200321条・异法方宜论篇第十二","description":"<p>2、岐伯对曰：地势使然也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200321,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2、岐伯对曰：地势使然也。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'jzQX5jQGzs4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4qsqQKmcAMo', 4, '{"title":"第20200322条・异法方宜论篇第十二","description":"<p>3、故东方之域。天地之所始生也。鱼盐之地。海滨傍水。其民食鱼而嗜咸。皆安其处。美其食。鱼者使人热中。盐者胜血。故其民皆黑色疏理。其病皆为痈疡。其治宜砭石。故砭石者。亦从东方来。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200322,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '3、故东方之域。天地之所始生也。鱼盐之地。海滨傍水。其民食鱼而嗜咸。皆安其处。美其食。鱼者使人热中。盐者胜血。故其民皆黑色疏理。其病皆为痈疡。其治宜砭石。故砭石者。亦从东方来。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'jzQX5jQGzs4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wUz1btpRzec', 4, '{"title":"第20200323条・异法方宜论篇第十二","description":"<p>4、西方者。金玉之域。沙石之处。天地之所收引也。其民陵居而多风。水土刚强。其民不衣而褐荐。其民华食而脂肥。故邪不能伤其形体。其病生于内。其治宜毒药。故毒药者。亦从西方来。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200323,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '4、西方者。金玉之域。沙石之处。天地之所收引也。其民陵居而多风。水土刚强。其民不衣而褐荐。其民华食而脂肥。故邪不能伤其形体。其病生于内。其治宜毒药。故毒药者。亦从西方来。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'jzQX5jQGzs4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GGplo15DLuZ', 4, '{"title":"第20200324条・异法方宜论篇第十二","description":"<p>5、北方者。天地所闭藏之域也。其地高陵居。风寒冰冽。其民乐野处而乳食。脏寒生满病。其治宜灸焫。故灸焫者。亦从北方来。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200324,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '5、北方者。天地所闭藏之域也。其地高陵居。风寒冰冽。其民乐野处而乳食。脏寒生满病。其治宜灸焫。故灸焫者。亦从北方来。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'jzQX5jQGzs4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('L1l6AsEKQ7d', 4, '{"title":"第20200325条・异法方宜论篇第十二","description":"<p>6、南方者。天地所长养。阳之所盛处也。其地下。水土弱。雾露之所聚也。其民嗜酸而食胕。故其民皆致理而赤色。其病挛痹。其治宜微针。故九针者。亦从南方来。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200325,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '6、南方者。天地所长养。阳之所盛处也。其地下。水土弱。雾露之所聚也。其民嗜酸而食胕。故其民皆致理而赤色。其病挛痹。其治宜微针。故九针者。亦从南方来。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'jzQX5jQGzs4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TQ3FPboRppy', 4, '{"title":"第20200326条・异法方宜论篇第十二","description":"<p>7、中央者。其地平以湿。天地所以生万物也众。其民食杂而不劳。故其病多痿厥寒热。其治宜导引按跷。故导引按跷者。亦从中央出也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200326,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '7、中央者。其地平以湿。天地所以生万物也众。其民食杂而不劳。故其病多痿厥寒热。其治宜导引按跷。故导引按跷者。亦从中央出也。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'jzQX5jQGzs4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hgcTInq1q4o', 4, '{"title":"第20200327条・异法方宜论篇第十二","description":"<p>8、故圣人杂合以治。各得其所宜。故治所以异而病皆愈者。得病之情。知治之大体也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200327,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '8、故圣人杂合以治。各得其所宜。故治所以异而病皆愈者。得病之情。知治之大体也。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'jzQX5jQGzs4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BZuxDEa38uy', 4, '{"title":"第20200328条・移精变气论篇第十三","description":"<p>1、黄帝问曰：余闻古之治病。惟其移精变气。可祝由而已。今世治病。毒药治其内。针石治其外。或愈或不愈。何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200328,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '1、黄帝问曰：余闻古之治病。惟其移精变气。可祝由而已。今世治病。毒药治其内。针石治其外。或愈或不愈。何也？', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'nFOcgR2jdj4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Cvqf3QidNvr', 4, '{"title":"第20200329条・移精变气论篇第十三","description":"<p>2、岐伯对曰：往古人居禽兽之间。动作以避寒。阴居以避暑。内无眷慕之累。外无伸宦之形。此恬憺之世。邪不能深入也。故毒药不能治其内。针石不能治其外。故可移精祝由而已。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200329,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2、岐伯对曰：往古人居禽兽之间。动作以避寒。阴居以避暑。内无眷慕之累。外无伸宦之形。此恬憺之世。邪不能深入也。故毒药不能治其内。针石不能治其外。故可移精祝由而已。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'nFOcgR2jdj4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vqJVflu1UG4', 4, '{"title":"第20200330条・移精变气论篇第十三","description":"<p>3、当今之世不然。忧患缘其内。苦形伤其外。又失四时之从。逆寒暑之宜。贼风数至。虚邪朝夕。内至五脏骨髓。外伤空窍肌肤。所以小病必甚。大病必死。故祝由不能已也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200330,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '3、当今之世不然。忧患缘其内。苦形伤其外。又失四时之从。逆寒暑之宜。贼风数至。虚邪朝夕。内至五脏骨髓。外伤空窍肌肤。所以小病必甚。大病必死。故祝由不能已也。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'nFOcgR2jdj4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8wTvqNUwdJ9', 4, '{"title":"第20200331条・移精变气论篇第十三","description":"<p>4、帝曰：善。余欲临病患。观死生。决嫌疑。欲知其要。如日月光。可得闻乎？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200331,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '4、帝曰：善。余欲临病患。观死生。决嫌疑。欲知其要。如日月光。可得闻乎？', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'nFOcgR2jdj4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('siOsE2qO5fj', 4, '{"title":"第20200332条・移精变气论篇第十三","description":"<p>5、岐伯曰：色脉者。上帝之所贵也。先师之所传也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200332,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '5、岐伯曰：色脉者。上帝之所贵也。先师之所传也。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'nFOcgR2jdj4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('eOYVCMWM1EM', 4, '{"title":"第20200333条・移精变气论篇第十三","description":"<p>6、上古使僦贷季。理色脉而通神明。合之金木水火土。四时八风六合。不离其常。变化相移。以观其妙。以知其要。欲知其要。则色脉是矣。色以应日。脉以应月。常求其要。则其要也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200333,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '6、上古使僦贷季。理色脉而通神明。合之金木水火土。四时八风六合。不离其常。变化相移。以观其妙。以知其要。欲知其要。则色脉是矣。色以应日。脉以应月。常求其要。则其要也。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'nFOcgR2jdj4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oc4YrhvZKqy', 4, '{"title":"第20200334条・移精变气论篇第十三","description":"<p>7、夫色之变化。以应四时之脉。此上帝之所贵。以合于神明也。所以远死而近生。生道以长。命曰圣王。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200334,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '7、夫色之变化。以应四时之脉。此上帝之所贵。以合于神明也。所以远死而近生。生道以长。命曰圣王。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'nFOcgR2jdj4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7tmGdaC4JJK', 4, '{"title":"第20200335条・移精变气论篇第十三","description":"<p>8、中古之治病。至而治之。汤液十日。以去八风五痹之病。十日不已。治以草苏草荄之枝。末为助。标本已得。邪气乃服。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200335,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '8、中古之治病。至而治之。汤液十日。以去八风五痹之病。十日不已。治以草苏草荄之枝。末为助。标本已得。邪气乃服。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'nFOcgR2jdj4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3c3Ykghg3hX', 4, '{"title":"第20200336条・移精变气论篇第十三","description":"<p>9、暮世之治病也则不然。治不本四时。不知日月。不审逆从。病形已成。乃欲微针治其外。汤液治其内。粗工凶凶。以为可攻。故病未已。新病复起。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200336,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '9、暮世之治病也则不然。治不本四时。不知日月。不审逆从。病形已成。乃欲微针治其外。汤液治其内。粗工凶凶。以为可攻。故病未已。新病复起。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'nFOcgR2jdj4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Kd6cLei0MQI', 4, '{"title":"第20200337条・移精变气论篇第十三","description":"<p>10、帝曰：愿闻要道。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200337,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '10、帝曰：愿闻要道。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'nFOcgR2jdj4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hz3Y4nukssy', 4, '{"title":"第20200338条・移精变气论篇第十三","description":"<p>11、岐伯曰：治之要极。无失色脉。用之不惑。治之大则。逆从倒行。标本不得。亡神失国。去故就新。乃得真人。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200338,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '11、岐伯曰：治之要极。无失色脉。用之不惑。治之大则。逆从倒行。标本不得。亡神失国。去故就新。乃得真人。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'nFOcgR2jdj4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KU9e1PoCyaF', 4, '{"title":"第20200339条・移精变气论篇第十三","description":"<p>12、帝曰：余闻其要于夫子矣。夫子言不离色脉。此余之所知也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200339,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '12、帝曰：余闻其要于夫子矣。夫子言不离色脉。此余之所知也。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'nFOcgR2jdj4');
