INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6N8AADp8uyd', 4, '{"title":"第20200347条・汤液醪醴论篇第十四","description":"<p>2、岐伯对曰：必以稻米。炊之稻薪。稻米者完。稻薪者坚。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200347,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2、岐伯对曰：必以稻米。炊之稻薪。稻米者完。稻薪者坚。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'x9wu54s2ytq');
