INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bYglMqVOK3x', 4, '{"title":"第20200349条・汤液醪醴论篇第十四","description":"<p>4、岐伯曰：此得天地之和。高下之宜。故能至完。伐取得时。故能至坚也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200349,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '4、岐伯曰：此得天地之和。高下之宜。故能至完。伐取得时。故能至坚也。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'x9wu54s2ytq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aj97M0npUAK', 4, '{"title":"第20200350条・汤液醪醴论篇第十四","description":"<p>5、帝曰：上古圣人作汤液醪醴。为而不用何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200350,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '5、帝曰：上古圣人作汤液醪醴。为而不用何也？', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'x9wu54s2ytq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('frgXr9w00nJ', 4, '{"title":"第20200351条・汤液醪醴论篇第十四","description":"<p>6、岐伯曰：自古圣人之作汤液醪醴者。以为备耳。夫上古作汤液。故为而弗服也。中古之世。道德稍衰。邪气时至。服之万全。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200351,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '6、岐伯曰：自古圣人之作汤液醪醴者。以为备耳。夫上古作汤液。故为而弗服也。中古之世。道德稍衰。邪气时至。服之万全。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'x9wu54s2ytq');
