INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jfZ1t6eRE1O', 4, '{"title":"第20200353条・汤液醪醴论篇第十四","description":"<p>8、岐伯曰：当今之世。必齐毒药攻其中。石针艾治其外也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200353,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '8、岐伯曰：当今之世。必齐毒药攻其中。石针艾治其外也。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'x9wu54s2ytq');
