INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bjfWcINTR9Z', 4, '{"title":"第20200357条・汤液醪醴论篇第十四","description":"<p>12、岐伯曰：针石。道也。精神不进。志意不治。故病不可愈。今精坏神去。荣卫不可复收。何者？嗜欲无穷。而忧患不止。精气弛坏。荣泣卫除。故神去之而病不愈也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200357,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '12、岐伯曰：针石。道也。精神不进。志意不治。故病不可愈。今精坏神去。荣卫不可复收。何者？嗜欲无穷。而忧患不止。精气弛坏。荣泣卫除。故神去之而病不愈也。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'x9wu54s2ytq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5GqCeG1zJLH', 4, '{"title":"第20200358条・汤液醪醴论篇第十四","description":"<p>13、帝曰：夫病之始生也。极微极精。必先入结于皮肤。今良工皆称曰：病成名曰逆。则针石不能治。良药不能及也。今良工皆得其法。守其数。亲戚兄弟远近音声日闻于耳。五色日见于目。而病不愈者。亦何暇不早乎。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200358,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '13、帝曰：夫病之始生也。极微极精。必先入结于皮肤。今良工皆称曰：病成名曰逆。则针石不能治。良药不能及也。今良工皆得其法。守其数。亲戚兄弟远近音声日闻于耳。五色日见于目。而病不愈者。亦何暇不早乎。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'x9wu54s2ytq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ifEg0xsaB1t', 4, '{"title":"第20200359条・汤液醪醴论篇第十四","description":"<p>14、岐伯曰：病为本。工为标。标本不得，邪气不服。此之谓也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200359,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '14、岐伯曰：病为本。工为标。标本不得，邪气不服。此之谓也。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'x9wu54s2ytq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wwvEM82SrkD', 4, '{"title":"第20200360条・汤液醪醴论篇第十四","description":"<p>15、帝曰：其有不毫毛而生。五脏阳以竭也。津液充郭。其魄独居。精孤于内。气耗于外。形不可与衣相保。此四极急而动中。是气拒于内。而形施于外，治之奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200360,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '15、帝曰：其有不毫毛而生。五脏阳以竭也。津液充郭。其魄独居。精孤于内。气耗于外。形不可与衣相保。此四极急而动中。是气拒于内。而形施于外，治之奈何？', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'x9wu54s2ytq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4zIrkR41JSi', 4, '{"title":"第20200361条・汤液醪醴论篇第十四","description":"<p>16、岐伯曰：平治于权衡。去宛陈挫。微动四极。温衣缪刺其处。以复其形。开鬼门。洁净府。精以时服。五阳已布。疏涤五脏。故精自生。形自盛。骨肉相保。巨气乃平。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200361,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '16、岐伯曰：平治于权衡。去宛陈挫。微动四极。温衣缪刺其处。以复其形。开鬼门。洁净府。精以时服。五阳已布。疏涤五脏。故精自生。形自盛。骨肉相保。巨气乃平。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'x9wu54s2ytq');
