INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('YioRbTmMVE7', 4, '{"title":"第20200384条・诊要经终论篇第十六","description":"<p>7、故春刺散俞。及与分理。血出而止。甚者传气。间者环也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200384,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '7、故春刺散俞。及与分理。血出而止。甚者传气。间者环也。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ERkGppOtOPO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ujpHuxuENtp', 4, '{"title":"第20200385条・诊要经终论篇第十六","description":"<p>8、夏刺络俞。见血而止。尽气闭环。痛病必下。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200385,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '8、夏刺络俞。见血而止。尽气闭环。痛病必下。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ERkGppOtOPO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IRkpMQJ2Rcf', 4, '{"title":"第20200386条・诊要经终论篇第十六","description":"<p>9、秋刺皮肤。循理。上下同法。神变而止。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200386,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '9、秋刺皮肤。循理。上下同法。神变而止。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ERkGppOtOPO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DyvHad9Vgos', 4, '{"title":"第20200387条・诊要经终论篇第十六","description":"<p>10、冬刺俞窍于分理。甚者直下。间者散下。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200387,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '10、冬刺俞窍于分理。甚者直下。间者散下。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ERkGppOtOPO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Y0BrpPcfHUR', 4, '{"title":"第20200388条・诊要经终论篇第十六","description":"<p>11、春夏秋冬。各有所刺。法其所在。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200388,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '11、春夏秋冬。各有所刺。法其所在。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ERkGppOtOPO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('EnHTEcr2mps', 4, '{"title":"第20200389条・诊要经终论篇第十六","description":"<p>12、春刺夏分。脉乱气微。入淫骨髓。病不能愈。令人不嗜食。又且少气。 春刺秋分。筋挛逆气。环为咳嗽。病不愈。令人时惊。又且哭。春刺冬分。邪气着藏。令人胀。病不愈。又且欲言语。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200389,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '12、春刺夏分。脉乱气微。入淫骨髓。病不能愈。令人不嗜食。又且少气。 春刺秋分。筋挛逆气。环为咳嗽。病不愈。令人时惊。又且哭。春刺冬分。邪气着藏。令人胀。病不愈。又且欲言语。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ERkGppOtOPO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5HgrSrNIb6z', 4, '{"title":"第20200390条・诊要经终论篇第十六","description":"<p>13、夏刺春分。病不愈。令人解惰。夏刺秋分。病不愈。令人心中欲无言。惕惕如人将捕之。夏刺冬分。病不愈。令人少气。时欲怒。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200390,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '13、夏刺春分。病不愈。令人解惰。夏刺秋分。病不愈。令人心中欲无言。惕惕如人将捕之。夏刺冬分。病不愈。令人少气。时欲怒。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ERkGppOtOPO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vQNoNC05CN9', 4, '{"title":"第20200391条・诊要经终论篇第十六","description":"<p>14、秋刺春分。病不已。令人惕然欲有所为。起而忘之。秋刺夏分。病不已。令人益嗜卧。又且善梦。秋刺冬分。病不已。令人洒洒时寒。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200391,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '14、秋刺春分。病不已。令人惕然欲有所为。起而忘之。秋刺夏分。病不已。令人益嗜卧。又且善梦。秋刺冬分。病不已。令人洒洒时寒。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ERkGppOtOPO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('WjI1XPS4lyB', 4, '{"title":"第20200392条・诊要经终论篇第十六","description":"<p>15、冬刺春分。病不已。令人欲卧不能眠。眠而有见。冬刺夏分。病不愈。气上。发为诸痹。冬刺秋分。病不已。令人善渴。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200392,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '15、冬刺春分。病不已。令人欲卧不能眠。眠而有见。冬刺夏分。病不愈。气上。发为诸痹。冬刺秋分。病不已。令人善渴。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ERkGppOtOPO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iUeZMM6Dx5f', 4, '{"title":"第20200393条・诊要经终论篇第十六","description":"<p>16、凡刺胸腹者。必避五脏。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200393,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '16、凡刺胸腹者。必避五脏。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ERkGppOtOPO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('QE01nkcYYEq', 4, '{"title":"第20200394条・诊要经终论篇第十六","description":"<p>17、中心者环死。刺中肝五日死。中脾者五日死。中肾者七日死。中肺者五日死。中膈者。皆为伤中。其病虽愈。不过一岁必死。刺避五藏者。知逆从也。所谓从者。膈与脾肾之处。知者反之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200394,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '17、中心者环死。刺中肝五日死。中脾者五日死。中肾者七日死。中肺者五日死。中膈者。皆为伤中。其病虽愈。不过一岁必死。刺避五藏者。知逆从也。所谓从者。膈与脾肾之处。知者反之。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ERkGppOtOPO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('As8KbcAr8NU', 4, '{"title":"第20200395条・诊要经终论篇第十六","description":"<p>18、刺胸腹者。必以布檄着之。乃从单布上刺。刺之不愈复刺。刺针必肃。刺肿摇针。经刺勿摇。此刺之道也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200395,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '18、刺胸腹者。必以布檄着之。乃从单布上刺。刺之不愈复刺。刺针必肃。刺肿摇针。经刺勿摇。此刺之道也。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ERkGppOtOPO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nA5r5J8XTs1', 4, '{"title":"第20200396条・诊要经终论篇第十六","description":"<p>19、帝曰：愿闻十二经脉之终奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200396,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '19、帝曰：愿闻十二经脉之终奈何？', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ERkGppOtOPO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XIKTc1iQHoN', 4, '{"title":"第20200397条・诊要经终论篇第十六","description":"<p>20、岐伯曰：太阳之脉。其终也戴眼反折螈。其色白。绝汗乃出。出则死矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200397,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '20、岐伯曰：太阳之脉。其终也戴眼反折螈。其色白。绝汗乃出。出则死矣。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ERkGppOtOPO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mTXnBx63JxA', 4, '{"title":"第20200398条・诊要经终论篇第十六","description":"<p>21、少阳终者。耳聋百节皆纵。目睘绝系。绝系一日半死。其死也色先青白。乃死矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200398,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '21、少阳终者。耳聋百节皆纵。目睘绝系。绝系一日半死。其死也色先青白。乃死矣。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ERkGppOtOPO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8R3JDXQJzGk', 4, '{"title":"第20200399条・诊要经终论篇第十六","description":"<p>22、阳明终者。口目动作。善惊妄言。色黄。其上下经盛。不仁。则终矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200399,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '22、阳明终者。口目动作。善惊妄言。色黄。其上下经盛。不仁。则终矣。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ERkGppOtOPO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9BiX3ETdUau', 4, '{"title":"第20200400条・诊要经终论篇第十六","description":"<p>23、少阴终者。面黑齿长而垢，腹胀闭。上下不通而终矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200400,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '23、少阴终者。面黑齿长而垢，腹胀闭。上下不通而终矣。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ERkGppOtOPO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('W1SWYFEO635', 4, '{"title":"第20200401条・诊要经终论篇第十六","description":"<p>24、太阴终者。腹胀闭不得息。善噫善呕。呕则逆。逆则面赤。不逆则上下不通。不通则面黑皮毛焦而终矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200401,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '24、太阴终者。腹胀闭不得息。善噫善呕。呕则逆。逆则面赤。不逆则上下不通。不通则面黑皮毛焦而终矣。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ERkGppOtOPO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('y2ZXlN50rom', 4, '{"title":"第20200402条・诊要经终论篇第十六","description":"<p>25、厥阴终者。中热嗌干。善溺心烦。甚则舌卷卵上缩而终矣。此十二经之所败也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200402,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '2024-09-26T13:53:11.000Z', '25、厥阴终者。中热嗌干。善溺心烦。甚则舌卷卵上缩而终矣。此十二经之所败也。', '2024-09-26T13:53:11.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'ERkGppOtOPO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VWFMgvEjpvD', 4, '{"title":"第20200403条・脉要精微论篇第十七","description":"<p>1、黄帝问曰：诊法何如？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200403,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '1、黄帝问曰：诊法何如？', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PaHSvgRCOBu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('z7bCcAQGeAt', 4, '{"title":"第20200404条・脉要精微论篇第十七","description":"<p>2、岐伯对曰：诊法常以平旦。阴气未动。阳气未散。饮食未进。经脉未盛。络脉调匀。气血未乱。故乃可诊有过之脉。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200404,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2、岐伯对曰：诊法常以平旦。阴气未动。阳气未散。饮食未进。经脉未盛。络脉调匀。气血未乱。故乃可诊有过之脉。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PaHSvgRCOBu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pQykm4Uxa20', 4, '{"title":"第20200405条・脉要精微论篇第十七","description":"<p>3、切脉动静而视精明。察五色观五藏有余不足。六腑强弱。形之盛衰。以此参伍。决死生之分。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200405,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '3、切脉动静而视精明。察五色观五藏有余不足。六腑强弱。形之盛衰。以此参伍。决死生之分。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PaHSvgRCOBu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2pTZ1z9s5fX', 4, '{"title":"第20200406条・脉要精微论篇第十七","description":"<p>4、夫脉者。血之府也。长则气治。短则气病。数则烦心。大则病进。上盛则气高。下盛则气胀。代则气衰。细则气少。涩则心痛。浑浑革革至如涌泉。病进而色弊。绵绵其去如弦绝。死。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200406,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '4、夫脉者。血之府也。长则气治。短则气病。数则烦心。大则病进。上盛则气高。下盛则气胀。代则气衰。细则气少。涩则心痛。浑浑革革至如涌泉。病进而色弊。绵绵其去如弦绝。死。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PaHSvgRCOBu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VIWoA7rhwI7', 4, '{"title":"第20200407条・脉要精微论篇第十七","description":"<p>5、夫精明五色者。气之华也。赤欲如白裹朱。不欲如赭。白欲如鹅羽。不欲如盐。青欲如苍璧之泽。不欲如蓝。黄欲如罗裹雄黄。不欲如黄土。黑欲如重漆色。不欲如地苍。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200407,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '5、夫精明五色者。气之华也。赤欲如白裹朱。不欲如赭。白欲如鹅羽。不欲如盐。青欲如苍璧之泽。不欲如蓝。黄欲如罗裹雄黄。不欲如黄土。黑欲如重漆色。不欲如地苍。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PaHSvgRCOBu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6KhkLnvLM89', 4, '{"title":"第20200408条・脉要精微论篇第十七","description":"<p>6、五色精微象见矣。其寿不久也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200408,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '6、五色精微象见矣。其寿不久也。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PaHSvgRCOBu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iZgtgwT5fIc', 4, '{"title":"第20200409条・脉要精微论篇第十七","description":"<p>7、夫精明者。所以视万物。别白黑。审短长。以长为短。以白为黑。如是则精衰矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200409,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '7、夫精明者。所以视万物。别白黑。审短长。以长为短。以白为黑。如是则精衰矣。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PaHSvgRCOBu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TmrYeVWb6v0', 4, '{"title":"第20200410条・脉要精微论篇第十七","description":"<p>8、五脏者。中之守也。中盛脏满。气胜伤恐者。声如从室中言。是中气之湿也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200410,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '8、五脏者。中之守也。中盛脏满。气胜伤恐者。声如从室中言。是中气之湿也。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PaHSvgRCOBu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oWiiuDg7N2W', 4, '{"title":"第20200411条・脉要精微论篇第十七","description":"<p>9、言而微。终日乃复言者。此夺气也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200411,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '9、言而微。终日乃复言者。此夺气也。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PaHSvgRCOBu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ltFX4Y3TEuK', 4, '{"title":"第20200412条・脉要精微论篇第十七","description":"<p>10、衣被不敛。言语善恶。不避亲疏者。此神明之乱也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200412,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '10、衣被不敛。言语善恶。不避亲疏者。此神明之乱也。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PaHSvgRCOBu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('t3aQ2TNQQ03', 4, '{"title":"第20200413条・脉要精微论篇第十七","description":"<p>11、仓廪不藏者。是门户不要也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200413,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '11、仓廪不藏者。是门户不要也。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PaHSvgRCOBu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ck7SkEV73Im', 4, '{"title":"第20200414条・脉要精微论篇第十七","description":"<p>12、水泉不止者。是膀胱不藏也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200414,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '12、水泉不止者。是膀胱不藏也。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PaHSvgRCOBu');
