INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pa1EayxZOrr', 4, '{"title":"第20200417条・脉要精微论篇第十七","description":"<p>15、头者精明之府。头倾视深。精神将夺矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200417,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '15、头者精明之府。头倾视深。精神将夺矣。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PaHSvgRCOBu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('UbgZfv890Nw', 4, '{"title":"第20200418条・脉要精微论篇第十七","description":"<p>16、背者胸中之府。背曲肩随。府将坏矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200418,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '16、背者胸中之府。背曲肩随。府将坏矣。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PaHSvgRCOBu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MU994lnRQlA', 4, '{"title":"第20200419条・脉要精微论篇第十七","description":"<p>17、腰者肾之府。转摇不能。肾将惫矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200419,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '17、腰者肾之府。转摇不能。肾将惫矣。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PaHSvgRCOBu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Du6BhqvnpPy', 4, '{"title":"第20200420条・脉要精微论篇第十七","description":"<p>18、膝者筋之府。屈伸不能。行则偻附。筋将惫矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200420,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '18、膝者筋之府。屈伸不能。行则偻附。筋将惫矣。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PaHSvgRCOBu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kRZq3MsgL03', 4, '{"title":"第20200421条・脉要精微论篇第十七","description":"<p>19、骨者髓之府。不能久立。行则振掉。骨将惫矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200421,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '19、骨者髓之府。不能久立。行则振掉。骨将惫矣。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PaHSvgRCOBu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zOBqm0UsVkD', 4, '{"title":"第20200422条・脉要精微论篇第十七","description":"<p>20、得强则生。失强则死。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200422,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '20、得强则生。失强则死。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PaHSvgRCOBu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4JSw77oXZ8n', 4, '{"title":"第20200423条・脉要精微论篇第十七","description":"<p>21、岐伯曰：反四时者。有余为精。不足为消。应太过。不足为精。应不足。有余为消。 阴阳不相应。病名曰关格。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200423,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '21、岐伯曰：反四时者。有余为精。不足为消。应太过。不足为精。应不足。有余为消。 阴阳不相应。病名曰关格。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PaHSvgRCOBu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qcvTgXEXHB2', 4, '{"title":"第20200424条・脉要精微论篇第十七","description":"<p>22、帝曰：脉其四时动奈何？知病之所在奈何？知病之所变奈何？知病乍在内奈何？知病乍在外奈何？请问此五者。可得闻乎？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200424,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '22、帝曰：脉其四时动奈何？知病之所在奈何？知病之所变奈何？知病乍在内奈何？知病乍在外奈何？请问此五者。可得闻乎？', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PaHSvgRCOBu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('I5GJWiAWpZi', 4, '{"title":"第20200425条・脉要精微论篇第十七","description":"<p>23、岐伯曰：请言其与天运转大也。万物之外。六合之内。天地之变。阴阳之应。彼春之暖。为夏之暑。彼秋之忿。为冬之怒。四变之动。脉与之上下。以春应中规。夏应中矩。秋应中衡。冬应中权。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200425,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '23、岐伯曰：请言其与天运转大也。万物之外。六合之内。天地之变。阴阳之应。彼春之暖。为夏之暑。彼秋之忿。为冬之怒。四变之动。脉与之上下。以春应中规。夏应中矩。秋应中衡。冬应中权。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PaHSvgRCOBu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OxFN6525Dy9', 4, '{"title":"第20200426条・脉要精微论篇第十七","description":"<p>24、是故冬至四十五日。阳气微上。阴气微下。夏至四十五日。阴气微上。阳气微下。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200426,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '24、是故冬至四十五日。阳气微上。阴气微下。夏至四十五日。阴气微上。阳气微下。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PaHSvgRCOBu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('S2cL6kAjK5B', 4, '{"title":"第20200427条・脉要精微论篇第十七","description":"<p>25、阴阳有时。与脉为期。期而相失。知脉所分。分之有期。故知死时。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200427,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '25、阴阳有时。与脉为期。期而相失。知脉所分。分之有期。故知死时。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PaHSvgRCOBu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mJQbGT3eKdY', 4, '{"title":"第20200428条・脉要精微论篇第十七","description":"<p>26、微妙在脉。不可不察。察之有纪。从阴阳始。始之有经。从五行生。生之有度。四时为宜。补泻勿失。与天地如一。得一之情。以知死生。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200428,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '26、微妙在脉。不可不察。察之有纪。从阴阳始。始之有经。从五行生。生之有度。四时为宜。补泻勿失。与天地如一。得一之情。以知死生。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PaHSvgRCOBu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MzaZu6isIJx', 4, '{"title":"第20200429条・脉要精微论篇第十七","description":"<p>27、是故声合五音。色合五行。脉合阴阳。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200429,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '27、是故声合五音。色合五行。脉合阴阳。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PaHSvgRCOBu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aUsG770Lh33', 4, '{"title":"第20200430条・脉要精微论篇第十七","description":"<p>28、是知阴盛则梦涉大水恐惧。阳盛则梦大火燔灼。阴阳俱盛则梦相杀毁伤。上盛则梦飞。下盛则梦堕。甚饱则梦予。甚饥则梦取。肝气盛则梦怒。肺气盛则梦哭。短虫多则梦聚众。长虫多则梦相击毁伤。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200430,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '28、是知阴盛则梦涉大水恐惧。阳盛则梦大火燔灼。阴阳俱盛则梦相杀毁伤。上盛则梦飞。下盛则梦堕。甚饱则梦予。甚饥则梦取。肝气盛则梦怒。肺气盛则梦哭。短虫多则梦聚众。长虫多则梦相击毁伤。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PaHSvgRCOBu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('k1lbR4gEg2f', 4, '{"title":"第20200431条・脉要精微论篇第十七","description":"<p>29、是故持脉有道。虚静为保。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200431,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '29、是故持脉有道。虚静为保。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PaHSvgRCOBu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('74A6VuQvK6L', 4, '{"title":"第20200432条・脉要精微论篇第十七","description":"<p>30、春日浮。如鱼之游在波。夏日在肤。泛泛乎万物有余。秋日下肤。蛰虫将去。冬日在骨。蛰虫周密。君子居室。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200432,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '30、春日浮。如鱼之游在波。夏日在肤。泛泛乎万物有余。秋日下肤。蛰虫将去。冬日在骨。蛰虫周密。君子居室。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PaHSvgRCOBu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zb0xEP2Vwk2', 4, '{"title":"第20200433条・脉要精微论篇第十七","description":"<p>31、故曰：知内者按而纪之。知外者终而始之。此六者。持脉之大法。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200433,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '31、故曰：知内者按而纪之。知外者终而始之。此六者。持脉之大法。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PaHSvgRCOBu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dAN6ISrGMiM', 4, '{"title":"第20200434条・脉要精微论篇第十七","description":"<p>32、心脉搏坚而长。当病舌卷不能言。其耎而散者。当消环自已。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200434,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '32、心脉搏坚而长。当病舌卷不能言。其耎而散者。当消环自已。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PaHSvgRCOBu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('U03wMiE2sxi', 4, '{"title":"第20200435条・脉要精微论篇第十七","description":"<p>33、肺脉搏坚而长。当病唾血。其耎而散者。当病灌汗。至令不复散发也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200435,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '33、肺脉搏坚而长。当病唾血。其耎而散者。当病灌汗。至令不复散发也。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PaHSvgRCOBu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1rr44TBuipG', 4, '{"title":"第20200436条・脉要精微论篇第十七","description":"<p>34、肝脉搏坚而长。色不青。当病坠若搏。因血在胁下。令人喘逆。其耎而散色泽者。当病溢饮。溢饮者渴暴多饮。而易入肌皮肠胃之外也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200436,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '34、肝脉搏坚而长。色不青。当病坠若搏。因血在胁下。令人喘逆。其耎而散色泽者。当病溢饮。溢饮者渴暴多饮。而易入肌皮肠胃之外也。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PaHSvgRCOBu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('s1iThjowE5z', 4, '{"title":"第20200437条・脉要精微论篇第十七","description":"<p>35、胃脉搏坚而长。其色赤。当病折髀。其耎而散者。当病食痹。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200437,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '35、胃脉搏坚而长。其色赤。当病折髀。其耎而散者。当病食痹。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PaHSvgRCOBu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ERXKmq7nva4', 4, '{"title":"第20200438条・脉要精微论篇第十七","description":"<p>36、脾脉搏坚而长。其色黄。当病少气。其耎而散色不泽者。当病足䯒肿。若水状也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200438,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '36、脾脉搏坚而长。其色黄。当病少气。其耎而散色不泽者。当病足䯒肿。若水状也。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PaHSvgRCOBu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SIwN2CIOSDS', 4, '{"title":"第20200439条・脉要精微论篇第十七","description":"<p>37、肾脉搏坚而长。其色黄而赤者。当病折腰。其耎而散者。当病少血。至令不复也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200439,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '37、肾脉搏坚而长。其色黄而赤者。当病折腰。其耎而散者。当病少血。至令不复也。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PaHSvgRCOBu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gtjsJnJRtwx', 4, '{"title":"第20200440条・脉要精微论篇第十七","description":"<p>38、帝曰：诊得心脉而急。此为何病？病形何如？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200440,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '38、帝曰：诊得心脉而急。此为何病？病形何如？', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PaHSvgRCOBu');
