INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NzCBzHHB3dc', 4, '{"title":"第20200447条・脉要精微论篇第十七","description":"<p>45、岐伯曰：风成为寒热。瘅成为消中。厥成为巅疾。久风为飧泄。脉风成为疠。病之变化。不可胜数。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200447,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '45、岐伯曰：风成为寒热。瘅成为消中。厥成为巅疾。久风为飧泄。脉风成为疠。病之变化。不可胜数。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PaHSvgRCOBu');
