INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mSMqAH7I4zK', 4, '{"title":"第20200449条・脉要精微论篇第十七","description":"<p>47、岐伯曰：此寒 气之肿。八风之变也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200449,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '47、岐伯曰：此寒 气之肿。八风之变也。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PaHSvgRCOBu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('g2QBqHjs5g2', 4, '{"title":"第20200450条・脉要精微论篇第十七","description":"<p>48、帝曰：治之奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200450,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '48、帝曰：治之奈何？', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PaHSvgRCOBu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xcMdK7NXmId', 4, '{"title":"第20200451条・脉要精微论篇第十七","description":"<p>49、岐伯曰：此四时之病。以其胜治之愈也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200451,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '49、岐伯曰：此四时之病。以其胜治之愈也。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PaHSvgRCOBu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('afp5hvjvu3R', 4, '{"title":"第20200452条・脉要精微论篇第十七","description":"<p>50、帝曰：有故病五脏发动。因伤脉色。各何以知其久暴至之病乎？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200452,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '50、帝曰：有故病五脏发动。因伤脉色。各何以知其久暴至之病乎？', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PaHSvgRCOBu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1SNCTHT0wUk', 4, '{"title":"第20200453条・脉要精微论篇第十七","description":"<p>51、岐伯曰：悉乎哉问也！征其脉小色不夺者。新病也。征其脉不夺其色夺者。此久病也。征其脉与五色俱夺者。此久病也。征其脉与五色俱不夺者。新病也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200453,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '51、岐伯曰：悉乎哉问也！征其脉小色不夺者。新病也。征其脉不夺其色夺者。此久病也。征其脉与五色俱夺者。此久病也。征其脉与五色俱不夺者。新病也。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PaHSvgRCOBu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('EjVFhHovyWl', 4, '{"title":"第20200454条・脉要精微论篇第十七","description":"<p>52、肝与肾脉并至。其色苍赤。当病毁伤不见血。已见血。湿若中水也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200454,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '52、肝与肾脉并至。其色苍赤。当病毁伤不见血。已见血。湿若中水也。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PaHSvgRCOBu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('WcTCBQVT1o7', 4, '{"title":"第20200455条・脉要精微论篇第十七","description":"<p>53、尺内两旁。则季胁也。尺外以候肾。尺里以候腹中。中附上。左外以候肝。内以候膈。右外以候胃。内以候脾。上附上。右外以候肺。内以候胸中。左外以候心。内以候膻中。前以候前。后以候后。上竟上者。胸喉中事也。下竟下者。少腹腰股膝胫足中事也。粗大者。阴不足阳有余。为热中也。来疾去徐。上实下虚。为厥巅疾。来徐去疾。上虚下实。为恶风也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200455,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '53、尺内两旁。则季胁也。尺外以候肾。尺里以候腹中。中附上。左外以候肝。内以候膈。右外以候胃。内以候脾。上附上。右外以候肺。内以候胸中。左外以候心。内以候膻中。前以候前。后以候后。上竟上者。胸喉中事也。下竟下者。少腹腰股膝胫足中事也。粗大者。阴不足阳有余。为热中也。来疾去徐。上实下虚。为厥巅疾。来徐去疾。上虚下实。为恶风也。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PaHSvgRCOBu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('G70ez77bx5Z', 4, '{"title":"第20200456条・脉要精微论篇第十七","description":"<p>54、故中恶风者。阳气受也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200456,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '54、故中恶风者。阳气受也。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PaHSvgRCOBu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('19SpDCpYhPX', 4, '{"title":"第20200457条・脉要精微论篇第十七","description":"<p>55、有脉俱沉细数者。少阴厥也。沉细数散者。寒热也。浮而散者为眴仆。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200457,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '55、有脉俱沉细数者。少阴厥也。沉细数散者。寒热也。浮而散者为眴仆。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PaHSvgRCOBu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Mq7Zilz4jyL', 4, '{"title":"第20200458条・脉要精微论篇第十七","description":"<p>56、诸浮不躁者皆在阳。则为热。其有躁者在手。诸细而沉者。皆在阴。则为骨痛。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200458,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '56、诸浮不躁者皆在阳。则为热。其有躁者在手。诸细而沉者。皆在阴。则为骨痛。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PaHSvgRCOBu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cZwWmuc3aTP', 4, '{"title":"第20200459条・脉要精微论篇第十七","description":"<p>57、其有静者在足。数动一代者。病在阳之脉也。泄及便脓血。诸过者切之。涩者阳气有余也。滑者阴气有余也。阳气有余为身热无汗。阴气有余为多汗身寒。阴阳有余则无汗而寒。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200459,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '57、其有静者在足。数动一代者。病在阳之脉也。泄及便脓血。诸过者切之。涩者阳气有余也。滑者阴气有余也。阳气有余为身热无汗。阴气有余为多汗身寒。阴阳有余则无汗而寒。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PaHSvgRCOBu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hE2pthkivXW', 4, '{"title":"第20200460条・脉要精微论篇第十七","description":"<p>58、推而外之。内而不外。有心腹积也。推而内之。外而不内，身有热也。推而上之。上而不下。腰足清也。推而下之。下而不上。头项痛也。按之至骨。脉气少者。腰脊痛而身有痹也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200460,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '58、推而外之。内而不外。有心腹积也。推而内之。外而不内，身有热也。推而上之。上而不下。腰足清也。推而下之。下而不上。头项痛也。按之至骨。脉气少者。腰脊痛而身有痹也。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PaHSvgRCOBu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('D5RZOSm1Bpd', 4, '{"title":"第20200461条・平人气象论篇第十八","description":"<p>1、黄帝问曰：平人何如？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200461,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '1、黄帝问曰：平人何如？', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', '2hMPpjIoW7D');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6TRGeWyPaAe', 4, '{"title":"第20200462条・平人气象论篇第十八","description":"<p>2、岐伯对曰：人一呼脉再动。一吸脉亦再动。呼吸定息脉五动。闰以太息。命曰平人。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200462,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2、岐伯对曰：人一呼脉再动。一吸脉亦再动。呼吸定息脉五动。闰以太息。命曰平人。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', '2hMPpjIoW7D');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Hhz4JlvSaJZ', 4, '{"title":"第20200463条・平人气象论篇第十八","description":"<p>3、平人者不病也。常以不病调病患。医不病。故为病患平息以调之为法。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200463,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '3、平人者不病也。常以不病调病患。医不病。故为病患平息以调之为法。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', '2hMPpjIoW7D');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cB7iM0hyOaq', 4, '{"title":"第20200464条・平人气象论篇第十八","description":"<p>4、人一呼脉一动。一吸脉一动。曰少气。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200464,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '4、人一呼脉一动。一吸脉一动。曰少气。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', '2hMPpjIoW7D');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aojJnN6CFRg', 4, '{"title":"第20200465条・平人气象论篇第十八","description":"<p>5、人一呼脉三动。一吸脉三动而躁。尺热曰病温。尺不热脉滑曰病风。脉涩曰痹。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200465,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '5、人一呼脉三动。一吸脉三动而躁。尺热曰病温。尺不热脉滑曰病风。脉涩曰痹。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', '2hMPpjIoW7D');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cc2weEIXV3H', 4, '{"title":"第20200466条・平人气象论篇第十八","description":"<p>6、人一呼脉四动以上曰死。脉绝不至曰死。乍疏乍数曰死。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200466,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '6、人一呼脉四动以上曰死。脉绝不至曰死。乍疏乍数曰死。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', '2hMPpjIoW7D');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JAvmTEpAGHH', 4, '{"title":"第20200467条・平人气象论篇第十八","description":"<p>7、平人之常气禀于胃。胃者平人之常气也。人无胃气曰逆。逆者死。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200467,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '7、平人之常气禀于胃。胃者平人之常气也。人无胃气曰逆。逆者死。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', '2hMPpjIoW7D');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xAn6yxMiJYn', 4, '{"title":"第20200468条・平人气象论篇第十八","description":"<p>8、春胃微弦曰平。弦多胃少曰肝病。但弦无胃曰死。胃而有毛曰秋病。毛甚曰今病。藏真散于肝。肝藏筋膜之气也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200468,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '8、春胃微弦曰平。弦多胃少曰肝病。但弦无胃曰死。胃而有毛曰秋病。毛甚曰今病。藏真散于肝。肝藏筋膜之气也。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', '2hMPpjIoW7D');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2u8JelDW3NY', 4, '{"title":"第20200469条・平人气象论篇第十八","description":"<p>9、夏胃微钩曰平。钩多胃少曰心病。但钩无胃曰死。胃而有石曰冬病。石甚曰今病。藏真通于心。心藏血脉之气也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200469,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '9、夏胃微钩曰平。钩多胃少曰心病。但钩无胃曰死。胃而有石曰冬病。石甚曰今病。藏真通于心。心藏血脉之气也。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', '2hMPpjIoW7D');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1IHYkpexmL1', 4, '{"title":"第20200470条・平人气象论篇第十八","description":"<p>10、长夏胃微弱曰平。弱多胃少曰脾病。但代无胃曰死。弱有石曰冬病。弱甚曰今病。藏真濡于脾。脾藏肌肉之气也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200470,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '10、长夏胃微弱曰平。弱多胃少曰脾病。但代无胃曰死。弱有石曰冬病。弱甚曰今病。藏真濡于脾。脾藏肌肉之气也。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', '2hMPpjIoW7D');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JlI68sxFMqM', 4, '{"title":"第20200471条・平人气象论篇第十八","description":"<p>11、秋胃微毛曰平。毛多胃少曰肺病。但毛无胃曰死。毛而有弦曰春病。弦甚曰今病。藏真高于肺。以行荣卫阴阳也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200471,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '11、秋胃微毛曰平。毛多胃少曰肺病。但毛无胃曰死。毛而有弦曰春病。弦甚曰今病。藏真高于肺。以行荣卫阴阳也。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', '2hMPpjIoW7D');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('t5zD6B4v2d7', 4, '{"title":"第20200472条・平人气象论篇第十八","description":"<p>12、冬胃微石曰平。石多胃少曰肾病。但石无胃曰死。石而有钩曰夏病。钩甚曰今病。藏真下于肾。肾藏骨髓之气也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200472,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '12、冬胃微石曰平。石多胃少曰肾病。但石无胃曰死。石而有钩曰夏病。钩甚曰今病。藏真下于肾。肾藏骨髓之气也。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', '2hMPpjIoW7D');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('I0oDe0sMwDK', 4, '{"title":"第20200473条・平人气象论篇第十八","description":"<p>13、胃之大络。名曰虚里。贯膈络肺。出于左乳下。其动应衣。脉宗气也。盛喘数绝者。则病在中。结而横。有积矣。绝不至曰死。乳之下其动应衣。宗气泄也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200473,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '13、胃之大络。名曰虚里。贯膈络肺。出于左乳下。其动应衣。脉宗气也。盛喘数绝者。则病在中。结而横。有积矣。绝不至曰死。乳之下其动应衣。宗气泄也。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', '2hMPpjIoW7D');
