INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Afqkq11t6Uc', 4, '{"title":"第20200508条・平人气象论篇第十八","description":"<p>48、夫平心脉来。累累如连珠。如循琅玕。曰心平。夏以胃气为本。病心脉来。喘喘连属。其中微曲。曰心病。死心脉来。前曲后居。如操带钩。曰心死。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200508,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '48、夫平心脉来。累累如连珠。如循琅玕。曰心平。夏以胃气为本。病心脉来。喘喘连属。其中微曲。曰心病。死心脉来。前曲后居。如操带钩。曰心死。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', '2hMPpjIoW7D');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Jv50bL4ChMr', 4, '{"title":"第20200509条・平人气象论篇第十八","description":"<p>49、平肺脉来。厌厌聂聂。如落榆荚。曰肺平。秋以胃气为本。病肺脉来。不上不下。如循鸡羽。曰肺病。死肺脉来。如物之浮。如风吹毛。曰肺死。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200509,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '49、平肺脉来。厌厌聂聂。如落榆荚。曰肺平。秋以胃气为本。病肺脉来。不上不下。如循鸡羽。曰肺病。死肺脉来。如物之浮。如风吹毛。曰肺死。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', '2hMPpjIoW7D');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('26XsLxaob1r', 4, '{"title":"第20200510条・平人气象论篇第十八","description":"<p>50、平肝脉来。耎弱招招。如揭长竿末梢。曰肝平。春以胃气为本。病肝脉来。盈实而滑。如循长竿。曰肝病。死肝脉来。急益劲。如新张弓弦。曰肝死。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200510,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '50、平肝脉来。耎弱招招。如揭长竿末梢。曰肝平。春以胃气为本。病肝脉来。盈实而滑。如循长竿。曰肝病。死肝脉来。急益劲。如新张弓弦。曰肝死。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', '2hMPpjIoW7D');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zKHtFfBrLud', 4, '{"title":"第20200511条・平人气象论篇第十八","description":"<p>51、平脾脉来。和柔相离。如鸡践地。曰脾平。长夏以胃气为本。病脾脉来。实而盈数。如鸡举足。曰脾病。死脾脉来。锐坚如鸟之喙。如鸟之距。如屋之漏。如水之流。曰脾死。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200511,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '51、平脾脉来。和柔相离。如鸡践地。曰脾平。长夏以胃气为本。病脾脉来。实而盈数。如鸡举足。曰脾病。死脾脉来。锐坚如鸟之喙。如鸟之距。如屋之漏。如水之流。曰脾死。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', '2hMPpjIoW7D');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8Y255yQ3nGh', 4, '{"title":"第20200512条・平人气象论篇第十八","description":"<p>52、平肾脉来。喘喘累累如钩。按之而坚。曰肾平。冬以胃气为本。病肾脉来。如引葛。按之益坚。曰肾病。死肾脉。发如夺索。辟辟如弹石。曰肾死。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200512,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '52、平肾脉来。喘喘累累如钩。按之而坚。曰肾平。冬以胃气为本。病肾脉来。如引葛。按之益坚。曰肾病。死肾脉。发如夺索。辟辟如弹石。曰肾死。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', '2hMPpjIoW7D');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xtT5pmFDX0W', 4, '{"title":"第20200513条・玉机真脏论篇第十九","description":"<p>1、黄帝问曰：春脉如弦。何如而弦？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200513,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '1、黄帝问曰：春脉如弦。何如而弦？', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3jTkQ1Eu7q1', 4, '{"title":"第20200514条・玉机真脏论篇第十九","description":"<p>2、岐伯对曰：春脉者肝也。东方木也。万物之所以始生也。故其气来。耎弱轻虚而滑。端直以长。故曰弦。反此者病。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200514,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2、岐伯对曰：春脉者肝也。东方木也。万物之所以始生也。故其气来。耎弱轻虚而滑。端直以长。故曰弦。反此者病。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('F972N4fsbSs', 4, '{"title":"第20200515条・玉机真脏论篇第十九","description":"<p>3、帝曰：何如而反？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200515,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '3、帝曰：何如而反？', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5ePMk52BtAJ', 4, '{"title":"第20200516条・玉机真脏论篇第十九","description":"<p>4、岐伯曰：其气来实而强。此谓太过。病在外。其气来不实而微。此谓不及。病在中。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200516,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '4、岐伯曰：其气来实而强。此谓太过。病在外。其气来不实而微。此谓不及。病在中。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('seN60tngzSJ', 4, '{"title":"第20200517条・玉机真脏论篇第十九","description":"<p>5、帝曰：春脉太过与不及。其病皆何如？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200517,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '5、帝曰：春脉太过与不及。其病皆何如？', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('18AHV5c78fR', 4, '{"title":"第20200518条・玉机真脏论篇第十九","description":"<p>6、岐伯曰：太过则令人善忘。忽忽眩冒而巅疾。其不及则令人胸痛引背。下则两胁胠满。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200518,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '6、岐伯曰：太过则令人善忘。忽忽眩冒而巅疾。其不及则令人胸痛引背。下则两胁胠满。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('n32TJANuZT6', 4, '{"title":"第20200519条・玉机真脏论篇第十九","description":"<p>7、帝曰：善。夏脉如钩。何如而钩？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200519,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '7、帝曰：善。夏脉如钩。何如而钩？', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
